#!/usr/bin/env python3
"""A small stdlib-only minijinja-cli compatible command line renderer."""
import argparse
import configparser
import json
import os
import sys
import urllib.parse

import advanced
import autoescape
import templating


def parse_define(text):
    if ':=' in text:
        k, v = text.split(':=', 1)
        try: value = json.loads(v)
        except Exception: value = v
    elif '=' in text:
        k, value = text.split('=', 1)
    else:
        k, value = text, True
    return k, value


def load_data(path, fmt):
    raw = sys.stdin.read() if path == '-' else open(path, encoding='utf-8').read()
    f = fmt
    if f == 'auto':
        ext = os.path.splitext(path)[1]
        f = {'.json':'json','.json5':'json','.toml':'toml','.ini':'ini','.conf':'ini','.config':'ini','.properties':'ini','.qs':'querystring','.yaml':'yaml','.yml':'yaml'}.get(ext)
        if f is None: raise ValueError('cannot detect format for ' + path)
    if f in ('json','json5'): return json.loads(raw)
    if f == 'toml':
        try:
            import tomllib
            return tomllib.loads(raw)
        except ImportError:
            result = {}; cur = result
            for line in raw.splitlines():
                line = line.split('#',1)[0].strip()
                if not line: continue
                if line.startswith('[') and line.endswith(']'):
                    cur = result
                    for part in line[1:-1].split('.'): cur = cur.setdefault(part,{})
                elif '=' in line:
                    k,v = line.split('=',1); v = v.strip()
                    try: cur[k.strip()] = json.loads(v)
                    except: cur[k.strip()] = v.strip('\"\'')
            return result
    if f == 'querystring':
        parsed = urllib.parse.parse_qs(raw, keep_blank_values=True)
        return {k: v[-1] if len(v)==1 else v for k,v in parsed.items()}
    if f == 'ini':
        p = configparser.ConfigParser()
        p.read_string(raw)
        out = {'default': dict(p.defaults())}
        for sec in p.sections(): out[sec] = dict(p.items(sec))
        return out
    if f == 'yaml':
        # Support JSON-compatible YAML and simple key/value mappings without dependencies.
        try: return json.loads(raw)
        except Exception: pass
        result = {}
        for line in raw.splitlines():
            line = line.split('#',1)[0].strip()
            if not line or ':' not in line: continue
            k,v=line.split(':',1); v=v.strip()
            if v.lower() in ('true','false'): val=v.lower()=='true'
            elif v.lower() in ('null','none','~'): val=None
            else:
                try: val=json.loads(v)
                except Exception: val=v.strip('"\'')
            result[k.strip()] = val
        return result
    raise ValueError('unsupported data format: '+f)


def select_data(ctx, selector):
    for part in selector.split('.'):
        if isinstance(ctx, dict): ctx = ctx.get(part)
        elif isinstance(ctx, list): ctx = ctx[int(part)]
        else: return None
    return ctx


def main(argv=None):
    p = argparse.ArgumentParser(prog='minijinja-cli', description='Render or evaluate jinja2 templates.')
    p.add_argument('template_file', nargs='?', default='-')
    p.add_argument('data_files', nargs='*')
    p.add_argument('-f','--format',default=os.environ.get('MINIJINJA_FORMAT','auto'),choices=['auto','cbor','ini','json','querystring','toml','yaml'])
    p.add_argument('-D','--define',action='append',default=[])
    p.add_argument('-t','--template')
    p.add_argument('-o','--output',default='-')
    p.add_argument('--select')
    p.add_argument('-a','--autoescape',default=os.environ.get('MINIJINJA_AUTOESCAPE','auto'),choices=['auto','html','json','none'])
    p.add_argument('--strict',action='store_true',default=os.environ.get('MINIJINJA_STRICT','').lower() in ('1','true'))
    p.add_argument('-n','--no-newline',action='store_true')
    p.add_argument('--trim-blocks',action='store_true')
    p.add_argument('--lstrip-blocks',action='store_true')
    p.add_argument('--py-compat',action='store_true')
    p.add_argument('-s','--syntax',action='append',default=[])
    p.add_argument('--env',action='store_true')
    p.add_argument('--no-include',action='store_true')
    p.add_argument('--safe-path',action='append',default=[])
    p.add_argument('--fuel',type=int,default=0)
    p.add_argument('-E','--expr')
    p.add_argument('--expr-out',default='print',choices=['print','json','json-pretty','status'])
    p.add_argument('--dump',choices=['instructions','ast','tokens'])
    p.add_argument('--repl',action='store_true')
    p.add_argument('-V','--version',action='version',version='minijinja-cli 2.20.0')
    p.add_argument('--print-config',action='store_true')
    p.add_argument('--config-file')
    p.add_argument('--long-help',action='store_true')
    p.add_argument('--syntax-help',action='store_true')
    args=p.parse_args(argv)
    if args.print_config:
        print('format = %r\nautoescape = %r\ninclude = %s\nnewline = %s\ntrim-blocks = %s\nlstrip-blocks = %s\npy-compat = %s\nenv = %s\nstrict = %s\nsafe-paths = %r\nexpr-out = %r\nfuel = %s\n' % (args.format,args.autoescape,str(not args.no_include).lower(),str(not args.no_newline).lower(),str(args.trim_blocks).lower(),str(args.lstrip_blocks).lower(),str(args.py_compat).lower(),str(args.env).lower(),str(args.strict).lower(),args.safe_path,args.expr_out,args.fuel))
        return 0
    if args.long_help or args.syntax_help:
        p.print_help(); return 0
    if args.template is not None:
        template=args.template; filename=None
    else:
        filename=args.template_file
        template=sys.stdin.read() if filename=='-' else open(filename,encoding='utf-8').read()
    ctx={}
    for path in args.data_files:
        data=load_data(path,args.format)
        if isinstance(data,dict): ctx.update(data)
        else: ctx['data']=data
    for d in args.define:
        k,v=parse_define(d); ctx[k]=v
    if args.env: ctx['ENV']=dict(os.environ)
    if args.select: ctx=select_data(ctx,args.select)
    if ctx is None: ctx={}
    if args.expr:
        val=templating.eval_expr(args.expr,ctx)
        out,status=advanced.expression_output(val,args.expr_out)
    else:
        syn={}
        for s in args.syntax:
            if '=' in s:
                k,v=s.split('=',1); syn[k]=v
        mode=autoescape.mode_for_template(args.autoescape,filename)
        out=templating.render(template,ctx,mode,args.strict,args.trim_blocks,args.lstrip_blocks,syn or None)
        if not args.no_newline and not out.endswith('\n'): out+='\n'
        status=0
    if args.output=='-': sys.stdout.write(out)
    else:
        with open(args.output,'w',encoding='utf-8') as f: f.write(out)
    return status

if __name__=='__main__':
    try: sys.exit(main())
    except (Exception,):
        print('error: rendering failed',file=sys.stderr)
        sys.exit(2)
